<?php
namespace Engenharia\Models;
class Nonconformities_model extends EngenhariaBaseModel { protected $table = 'eng_nonconformities'; public function __construct(){ parent::__construct($this->table); } public function forResponse(int $response_id){return $this->db->table($this->db->prefixTable($this->table))->where('response_id',$response_id)->where('deleted',0)->get(1)->getRow();} public function forLaudo(int $id){return $this->db->table($this->db->prefixTable($this->table))->where('laudo_id',$id)->where('deleted',0)->orderBy('severity','DESC')->get();} public function summary(int $id){$rows=$this->forLaudo($id)->getResult();$out=array('low'=>0,'medium'=>0,'high'=>0,'critical'=>0);foreach($rows as $row){if(isset($out[$row->severity]))$out[$row->severity]++;}return$out;} public function saveForResponse(array $data,int $id=0):int{$t=$this->db->prefixTable($this->table);if($id){$this->db->table($t)->where('id',$id)->update($data);return $id;}if(empty($data['code'])){$count=$this->db->table($t)->where('laudo_id',(int)$data['laudo_id'])->countAllResults();$data['code']='NC-'.date('Y').'-'.str_pad((string)($count+1),4,'0',STR_PAD_LEFT);}$data+=array('status'=>'open','deleted'=>0,'created_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s'));$this->db->table($t)->insert($data);return(int)$this->db->insertID();} }
